function sourceImage(e){if(['parliament','paper-hinduism','parliament-close','chicago-arrive'].includes(e.id))return photos.find(p=>p.id==='chicago-1893');if(e.id==='srinagar98')return photos.find(p=>p.id==='kashmir-group-1898');return null}
