 $('detail-content').innerHTML=`<div class="detail-top"><span class="chapter-number" style="color:${j.color}">${String(j.number).padStart(2,'0')}</span><div><p class="eyebrow">JOURNEY CONNECTION</p><div class="chapter-label">${escapeHTML(j.name)}</div></div></div><div class="detail-body route-panel"><div class="event-date"><span>${r.status==='documented'?'Documented stop order':'Illustrative connection'}</span></div><h2 tabindex="-1">${escapeHTML(la.name)} to ${escapeHTML(lb.name)}</h2><div class="route-stops"><p><strong>${escapeHTML(la.name)}</strong><small>${escapeHTML(a.date)}</small></p><p><strong>${escapeHTML(lb.name)}</strong><small>${escapeHTML(b.date)}</small></p></div><h3>Travel</h3><p>${escapeHTML(r.mode)}</p><p class="evidence-note">${escapeHTML(r.note)}</p><h3>How the line is drawn</h3><p>Arrows show the displayed direction. The line connects selected stops for orientation. It does not identify the exact road, railway, sea lane or every intermediate stop.</p><h3>Source</h3>${refsHTML(r.sources)}<div class="route-actions"><button id="route-from">Open first stop</button><button id="route-to">Open next stop</button></div></div>`;
