function matches(e){const j=journeyById[e.journey],l=data.locations[e.location],q=$('search').value.trim().toLowerCase();return (!$('journey').value||e.journey===$('journey').value)&&(!$('year').value||e.startYear<=+$('year').value&&e.endYear>=+$('year').value)&&(!$('country').value||l.country===$('country').value)&&(!$('phase').value||j.phase===$('phase').value)&&(!q||[e.title,e.description,e.people,l.name,l.present,e.date].join(' ').toLowerCase().includes(q))}
