function pause(){playing=false;clearTimeout(playTimer);$('play').innerHTML='▶ <span>Play journey</span>';$('play').setAttribute('aria-label','Play journey');$('play').setAttribute('aria-pressed','false')}
function tick(){if(!playing)return;let i=filtered.findIndex(e=>e.id===selectedId);if(i===filtered.length-1){pause();$('announcement').textContent='Journey finished';return}selectEvent(filtered[i+1].id);playTimer=setTimeout(tick,2800/+$('speed').value)}
