function bind(){filterIds.forEach(id=>$(id).onchange=()=>applyFilters());let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>applyFilters(),180)};$('reset').onclick=()=>resetFilters();$('global-view').onclick=()=>setView('global');$('india-view').onclick=()=>setView('india');$('journey-view').onclick=()=>setView('journey');$('show-routes').onchange=()=>{renderMap();highlightSelection()};$('legend-button').onclick=()=>{const hidden=$('journey-legend').hidden;$('journey-legend').hidden=!hidden;$('legend-button').setAttribute('aria-expanded',hidden)};$('play').onclick=play;$('speed').onchange=()=>{if(playing){clearTimeout(playTimer);playTimer=setTimeout(tick,2800/+$('speed').value)}};$('restart').onclick=()=>{pause();if(filtered.length)selectEvent(filtered[0].id)};$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});}
