let tourIndex=0,tourTarget=null;
function closeTour(remember=true){$('site-tour').hidden=true;tourTarget?.classList.remove('tour-highlight');tourTarget=null;if(remember)try{localStorage.setItem('vivekananda-tour-seen','1')}catch{}document.body.classList.remove('tour-open')}
function showTourStep(){const step=tourSteps[tourIndex];tourTarget?.classList.remove('tour-highlight');tourTarget=document.querySelector(step.selector);tourTarget?.classList.add('tour-highlight');tourTarget?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});$('tour-step').textContent=`Quick guide · ${tourIndex+1} of ${tourSteps.length}`;$('tour-title').textContent=step.title;$('tour-copy').textContent=step.copy;$('tour-next').textContent=tourIndex===tourSteps.length-1?'Start exploring':'Next';setTimeout(()=>$('tour-next').focus({preventScroll:true}),250)}
